 30	\begin{lemma}[Linearity and inversion of the full-field decoder]\label{lem:qld-decoder-linearity}
 31		\lean{MIPStarRE.QPBT.decodeFq_add, MIPStarRE.QPBT.decodeFq_smul, MIPStarRE.QPBT.decodeFq_lowDegreeEncoding}
 32		\leanok
 33		\uses{def:qld-full-field-decoder}
 34		For bounded polynomial representatives $g,g'$ and $c\in\F_q$, one has
 35		\[
 36			\mathrm{Dec}_{\F_q}(g+g')=\mathrm{Dec}_{\F_q}(g)+\mathrm{Dec}_{\F_q}(g'),
 37			\qquad
 38			\mathrm{Dec}_{\F_q}(cg)=c\,\mathrm{Dec}_{\F_q}(g),
 39		\]
 40		and $\mathrm{Dec}_{\F_q}(g_h)=h$ for every $h\in\F_q^M$.
 41	\end{lemma}
 42	\begin{proof}
 43		\leanok
 44		\uses{def:qld-full-field-decoder, def:low-degree-encoding,
 45			def:decoding-map}
 46		The decoder is given coordinatewise by evaluation of the representative at the points of the hypercube, and evaluation at a fixed point is $\F_q$-linear in the representative, which gives the two displayed identities. For the third, the multilinear encoding $g_h$ takes the value $h_y$ at each point $y$ of the hypercube, because the indicator polynomials of \eqref{eq:low-degree-encoding-definition} vanish at every other such point; hence the vector of its evaluations is $h$.
 47	\end{proof}
